class Base {
protected:
    int data;
public:
    Base(int x) : data(x) {}
    // Virtual destructor hints at complex state,
    // demanding optimization of derived construction.
    virtual ~Base() = default;
};

class Derived : public Base {
public:
    // Compiler generates forwarding constructors (C++11/14).
    // e.g., Derived(int x) : Base(x) {}
    using Base::Base; 
};

// Optimized Construction: Derived d(10);
// No temporary Base object is created and copied/moved;
// Base construction occurs directly within the Derived object memory.
